    promptLabel: "文法形式選擇",
    instructionZh: "句中填空：依文脈選最自然的文法。",
    instructionI18n: { "ja": "文中の空欄をうめる問題です。文脈に合う、いちばん自然な文法を選びましょう。", "en": "Fill in the blank: choose the grammar that fits the sentence most naturally." },
    promptText: "土曜日、いっしょに えいがを 見 ___ 。",
