    explanationI18n: { "ja": "友だちが「わたしの家」のほうへ移動してくるので、「来ます」＝来る、を使います。「行きます」は話し手から離れる方向の「行く」で、「わたしの家に来る」と矛盾します。「食べます」は食べる、「見ます」は見るです。話し手のほうへ移動してくるのは「来ます」だけが正しくなります。", "en": "The friend moves toward 「わたしの家」, over here, so use 来ます — \"come.\" 行きます means \"go\" away from the speaker and contradicts \"come to my house\"; 食べます is \"eat\"; 見ます is \"look.\" For movement toward the speaker, only 来ます works." },
