    explanationI18n: { "ja": "「たくさん入る（たくさん入る）」はサイズが大きいことに対応するので、「大きい」を使います。「小さい」は小さいで、たくさん入ることと矛盾します。「新しい」は新しさで容量とは関係がなく、「高い」は値段や高さで、たくさん入ることとは関係がありません。容量が大きいことをあらわすのは「大きい」だけが正しくなります。", "en": "「たくさん入る (holds a lot)」 corresponds to a large size, so use 大きい — \"big.\" 小さい is \"small\" and contradicts holding a lot; 新しい is about new vs. old, unrelated to capacity; 高い is \"expensive / tall,\" unrelated to holding a lot. To describe large capacity, only 大きい works." },
