    explanationI18n: { "ja": "「忙しくて何かをする～がない」というのは時間帯のことなので、「時間」を使います。「食べる時間がありません」＝食べる時間がない、という意味です。「お金」はお金で忙しさとは関係がなく、「ところ」は場所、「ことば」は言葉です。取れない時間帯をあらわすのは「時間」だけが正しくなります。", "en": "\"So busy there's no ~ to do something\" refers to a span of time, so use 時間 — \"time,\" and 「食べる時間がありません」 means \"there's no time to eat.\" お金 is \"money,\" unrelated to being busy; ところ is \"place\"; ことば is \"words.\" For a span of time you can't spare, only 時間 works." },
