    hintI18n: { "ja": "朝、目が覚めて布団から出て一日を始める動作です。", "en": "The action of waking in the morning, getting out of bed, and starting your day." },
    expectedAnswer: "起きます",
    options: ["起きます", "ねます", "やすみます", "かえります"],
