    explanationI18n: { "ja": "「六時に起きて、かおをあらいます」＝六時に起きて顔を洗う、という意味で、朝目覚めて布団から出るときは「起きます」を使います。「ねます」は『寝る』で、朝活動を始めるのとは逆です。「やすみます」は『休む／欠席する』、「かえります」は『帰る』です。朝目覚めて一日を始める場面で成り立つのは「起きます」だけです。", "en": "「六時に起きて、かおをあらいます」 means \"get up at six and wash your face\"; waking in the morning and getting out of bed uses 起きます. ねます is \"go to sleep,\" the opposite of starting the day; やすみます is \"rest / take off\"; かえります is \"go back.\" For waking in the morning and starting the day, only 起きます works." },
