    promptLabel: "詞彙填空",
    instructionZh: "句中填空：選最自然的詞語。",
    instructionI18n: { "ja": "文中の空欄補充：最も自然な語を選びましょう。", "en": "Fill in the blank: choose the most natural word." },
    promptText: "この みせの やさいは ___ ので、よく かいます。",
    promptContextZh: "這家店的蔬菜很便宜，所以我常買。",
