    explanationI18n: { "ja": "「きのう かいました…新しいかばん」＝昨日買ったばかりの新しいかばん、という意味で、買ったばかりで使っていないときは「新しい」を使います。「ふるい」は『古い』で、昨日買ったばかりであることと矛盾します。「おもい」は『重い』で重さを、「ながい」は『長い』で長さを形容します。買ったばかりの新品を形容できるのは「新しい」だけです。", "en": "「きのう かいました…新しいかばん」 means \"a new bag I just bought yesterday\"; something just bought and unused uses 新しい. ふるい is \"old,\" contradicting having bought it yesterday; おもい is \"heavy,\" describing weight; ながい is \"long,\" describing length. For a brand-new item just purchased, only 新しい works." },
