    explanationI18n: { "ja": "「あしたの天気はあめ」＝明日の天気は雨、という意味で、晴れや雨などの大気の状況は「天気」を使います。「げんき」は『元気／健康』、「びょうき」は『病気』、「でんき」は『電気／電灯』です。読み方は似ていますが、晴雨の状況を言うときに成り立つのは「天気」だけです。", "en": "「あしたの天気はあめ」 means \"tomorrow's weather is rain\"; atmospheric conditions like sun and rain use 天気. げんき is \"spirit / health\"; びょうき is \"illness\"; でんき is \"electricity / lights.\" Though the readings are similar, for describing sun and rain only 天気 works." },
