    meaningI18n: { "ja": "友達", "en": "friend" },
    promptLabel: "漢字読み",
    instructionZh: "選出底線詞語的正確讀音。",
    instructionI18n: { "ja": "下線部の語の正しい読み方を選びましょう。", "en": "Choose the correct reading of the underlined word." },
    promptText: "あした「友達」と こうえんで あそびます。",
