    instructionI18n: { "ja": "「」の中の言葉に最も意味が近い選択肢を選びなさい。", "en": "Choose the option closest in meaning to the word in「」." },
    promptText: "あの 店の 人は とても 「親切」です。",
    promptContextZh: "那家店的人非常親切。",
    promptContextI18n: { "ja": "あの店の人はとても親切です。", "en": "The people at that shop are very kind." },
